using System;using System.Linq;using System.IO;using System.Drawing;using System.Reflection;using System.Web.Script.Serialization;
class TavernBusinessChecks{static void Check(bool b,string n){if(!b)throw new Exception(n);}[STAThread]static void Main(){var s=new Save();int xp=s.xp;Check(!TavernBusiness.Begin(s,"words"),"locked");foreach(var id in WaystationChapterOne.Ids.Take(5))s.completed.Add(id);Check(!TavernBusiness.Unlocked(s),"sixth required");s.completed.Add(WaystationChapterOne.Ids.Last());int start=s.rogue.coins;Check(TavernBusiness.Begin(s,"words"),"begin");TavernBusiness.Begin(s,"words");Check(s.rogue.coins==start+100&&!TavernBusiness.Skip(s),"base once");Check(TavernBusiness.Reward(s,"a",false)==0,"wrong");Check(TavernBusiness.Reward(s,"a",true)==5&&TavernBusiness.Reward(s,"a",true)==0,"duplicate");var json=new JavaScriptSerializer();s=json.Deserialize<Save>(json.Serialize(s));for(int i=0;i<20;i++)TavernBusiness.Reward(s,"b"+i,true);Check(s.tavernBusiness.bonusCoins==50&&s.rogue.coins==start+150&&s.xp==xp,"cap no XP");Check(TavernBusiness.Settle(s)&&!TavernBusiness.Settle(s),"settle once");Check(TavernBusiness.Reward(s,"c",true)==0,"free practice");TavernBusiness.NextDay(s);Check(TavernBusiness.Skip(s)&&!TavernBusiness.Skip(s)&&s.rogue.coins==start+200,"skip 50");var bank=json.Deserialize<TavernListeningGroup[]>(File.ReadAllText("D:/WORK/Cet6Story/assets/tavern/listening/groups.json"));foreach(int level in new[]{4,6})Check(bank.Where(g=>g.level==level).Sum(g=>g.questions.Count)==10,"daily plan available");foreach(var group in bank)Check(File.Exists("D:/WORK/Cet6Story/assets/tavern/listening/"+group.audio)&&group.questions.All(q=>q.options.Length==4&&q.answer>=0&&q.answer<4),"demo bank valid");using(var game=new Game()){var f=BindingFlags.Instance|BindingFlags.NonPublic;s.tavernBusiness=new TavernBusinessState{introduced=true};typeof(Game).GetField("save",f).SetValue(game,s);game.Show();typeof(Game).GetMethod("ShowTavernBusiness",f).Invoke(game,null);using(var shot=new Bitmap(game.Width,game.Height)){game.DrawToBitmap(shot,game.ClientRectangle);shot.Save("D:/WORK/Cet6Story/.validation/tavern-business-preview.png");}TavernBusiness.Begin(s,"words");typeof(Game).GetMethod("ShowTavernWords",f).Invoke(game,new object[]{4});}Console.WriteLine("PASS unlock, daily cap, skip, no XP, persistence, sample bank and live pages");}}
